def is_woodall(x):
    if x < 1:
        return False
    target = x + 1  # Woodall numbers satisfy x + 1 == n * 2**n for some n >= 1
    n = 1
    while n * (1 << n) <= target:
        if n * (1 << n) == target:
            return True
        n += 1
    return False
